2. import { GraphQLTagPluckOptions } from './index.js';
3. import { getExtNameFromFilePath } from './libs/extname.js';
4. 
5. export default function generateConfig(
6.   filePath: string,
7.   code: string,
8.   _options: GraphQLTagPluckOptions,
9. ): ParserOptions {
10.   const plugins: any[] = [
11.     'asyncGenerators',
12.     'bigInt',
13.     'classProperties',
14.     'classPrivateProperties',
15.     'classPrivateMethods',
16.     'decorators-legacy',
17.     'doExpressions',
18.     'dynamicImport',
19.     'explicitResourceManagement',
20.     'exportDefaultFrom',
21.     'exportNamespaceFrom',
22.     'functionBind',
23.     'functionSent',
24.     'importMeta',
25.     'logicalAssignment',
26.     'nullishCoalescingOperator',
27.     'numericSeparator',
28.     'objectRestSpread',
29.     'optionalCatchBinding',
30.     'optionalChaining',
31.     ['pipelineOperator', { proposal: 'smart' }],
32.     'throwExpressions',
33.   ];
34. 
35.   // { all: true } option is bullshit thus I do it manually, just in case
36.   // I still specify it
37.   const flowPlugins = [['flow', { all: true }], 'flowComments'];
38. 
39.   // If line has @flow header, include flow plug-ins
40.   const dynamicFlowPlugins = code.includes('@flow') ? flowPlugins : [];
41. 
42.   const fileExt = getExtNameFromFilePath(filePath);
43.   switch (fileExt) {
44.     case '.ts':
45.     case '.cts':
46.     case '.mts':
47.       plugins.push('typescript');
48.       plugins.push('importAssertions');
49.       break;
50.     case '.tsx':
51.       plugins.push('typescript', 'jsx');
52.       plugins.push('importAssertions');
53.       break;
54.     // Adding .jsx extension by default because it doesn't affect other syntax features
55.     // (unlike .tsx) and because people are seem to use it with regular file extensions
56.     // (e.g. .js) see https://github.com/dotansimha/graphql-code-generator/issues/1967
57.     case '.js':
58.     case '.mjs':
59.     case '.cjs':
60.       plugins.push('jsx', ...dynamicFlowPlugins);
61.       break;
62.     case '.jsx':
63.       plugins.push('jsx', ...dynamicFlowPlugins);
64.       break;
65.     case '.flow.js':
66.       plugins.push('jsx', ...flowPlugins);
67.       break;
68.     case '.flow.jsx':
69.       plugins.push('jsx', ...flowPlugins);
70.       break;
71.     case '.flow':
72.       plugins.push('jsx', ...flowPlugins);
73.       break;
74.     case '.vue':
75.       plugins.push('typescript', 'vue');
76.       break;
77.     case '.svelte':
78.       plugins.push('typescript', 'svelte');
79.       break;
80.     case '.astro':
81.       plugins.push('typescript', 'jsx');
82.       break;
83.     case '.gts':
84.       plugins.push('typescript');
85.       break;
86.     case '.gjs':
87.       // .gjs files need to be parsed as TypeScript because Ember relies on decorators, which are handled by TypeScript.
88.       // without this, it throws a SyntaxError: Unexpected token, expected "{"
89.       // when native decorators are supported, we should remove this
90.       plugins.push('typescript');
91.       break;
92.     default:
93.       plugins.push('jsx', ...dynamicFlowPlugins);
94.       break;
95.   }
96. 
97.   // The _options filed will be used to retrieve the original options.
98.   // Useful when we wanna get not config related options later on
99.   return {
100.     sourceType: 'module',
101.     plugins,
102.     allowUndeclaredExports: true,
103.     sourceFilename: filePath,
104.   };
105. }
106.

