275.             return;
276.           }
277.           if (!isIdentifier(path.parent.id)) {
278.             return;
279.           }
280. 
281.           definedIdentifierNames.push(path.parent.id.name);
282. 
283.           return;
284.         }
285. 
286.         // Checks to see if a node represents a typescript '<expression> as const' expression
287.         function isTSAsConstExpression(node: any): node is TSAsExpression {
288.           return (
289.             isTSAsExpression(node) &&
290.             isTSTypeReference(node.typeAnnotation) &&
291.             isIdentifier(node.typeAnnotation.typeName) &&
292.             node.typeAnnotation.typeName.name === 'const'
293.           );
294.         }
295. 
296.         // Extract template literal from as const expression if applicable
297.         // e.g. gql(`query myQuery {}` as const)
298.         const unwrappedExpression = isTSAsConstExpression(arg0) ? arg0.expression : arg0;
299. 
300.         // Push strings template literals to gql calls
301.         // e.g. gql(`query myQuery {}`) -> query myQuery {}
302.         if (
303.           isIdentifier(path.node.callee) &&
304.           isValidIdentifier(path.node.callee.name) &&
305.           isTemplateLiteral(unwrappedExpression)
306.         ) {
307.           const { start, end, loc } = unwrappedExpression;
308.           if (start != null && end != null && start != null && loc != null) {
309.             const gqlTemplateLiteral = pluckStringFromFile(
310.               code,
311.               unwrappedExpression as any,
312.               hooksOptions,
313.             );
314. 
315.             // If the entire template was made out of interpolations it should be an empty
316.             // string by now and thus should be ignored
317.             if (gqlTemplateLiteral) {
318.               addTemplateLiteralToResult({
319.                 content: gqlTemplateLiteral,
320.                 loc,
321.                 end,
322.                 start,
323.               });
324.             }
325.           }
326.         }
327.       },
328.     },
329. 
330.     ImportDeclaration: {
331.       enter(path) {
332.         // Find the identifier name used from graphql-tag, es6
333.         // e.g. import gql from 'graphql-tag' -> gql
334.         if (!isValidPackage(path.node.source.value)) {
335.           return;
336.         }
337. 
338.         const moduleNode = modules.find(
339.           pkg => pkg.name.toLowerCase() === path.node.source.value.toLowerCase(),
